import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

const Checkout = () => {
  const navigate = useNavigate();

  const [payment, setPayment] = useState("cod");

  const [address, setAddress] = useState({
    full: "",
    pincode: "",
    alt: ""
  });

  const [timeLeft, setTimeLeft] = useState(120);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login first 🔐");
      navigate("/login");
    }
  }, [navigate]);

  useEffect(() => {
    let timer;

    if (payment === "qr" && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    }

    return () => clearInterval(timer);
  }, [payment, timeLeft]);

  const formatTime = () => {
    const min = Math.floor(timeLeft / 60);
    const sec = timeLeft % 60;
    return `${min}:${sec < 10 ? "0" : ""}${sec}`;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login first 🔐");
      navigate("/login");
      return;
    }

    try {
      const res = await axios.post("http://localhost:5000/place-order", {
        userId: user._id,
        name: user.name,
        address: address.full,
        pincode: address.pincode,
        altAddress: address.alt,
        paymentMethod: payment
      });

      localStorage.setItem("latestOrderId", res.data.order._id);
      localStorage.setItem("lastAddress", JSON.stringify(address));

      if (payment === "qr") {
        alert("Payment under verification ⏳");
        navigate("/payment-pending");
      } else {
        alert("Order Placed ✅");
        navigate("/order-success");
      }
    } catch (err) {
      alert("Order failed ❌");
    }
  };

  return (
    <div style={container}>
      <h1 style={{ textAlign: "center" }}>Checkout</h1>

      {/* PAYMENT OPTIONS */}
      <div style={card}>
        <h3>Select Payment Method</h3>

        <label style={radio}>
          <input
            type="radio"
            value="cod"
            checked={payment === "cod"}
            onChange={(e) => setPayment(e.target.value)}
          />
          Cash on Delivery
        </label>

        <label style={radio}>
          <input
            type="radio"
            value="qr"
            checked={payment === "qr"}
            onChange={(e) => {
              setPayment(e.target.value);
              setTimeLeft(120);
            }}
          />
          Pay Online
        </label>
      </div>

      {/* ADDRESS */}
      <div style={card}>
        <h3>Delivery Address</h3>

        <input
          placeholder="Full Address"
          value={address.full}
          onChange={(e) =>
            setAddress({ ...address, full: e.target.value })
          }
          style={input}
        />

        <input
          placeholder="Pincode"
          value={address.pincode}
          onChange={(e) =>
            setAddress({ ...address, pincode: e.target.value })
          }
          style={input}
        />

        <input
          placeholder="Alternate Address"
          value={address.alt}
          onChange={(e) =>
            setAddress({ ...address, alt: e.target.value })
          }
          style={input}
        />
      </div>

      {/* QR PAYMENT */}
      {payment === "qr" && (
        <div style={card}>
          <h3>Scan & Pay</h3>

          <img
            src="/my-qr.png.png.jpeg"
            alt="QR Code"
            style={{ width: "220px", display: "block", margin: "20px auto" }}
          />

          <p style={{ textAlign: "center", fontWeight: "bold" }}>
            Pay within {formatTime()}
          </p>

          <button onClick={handleSubmit} style={checkoutBtn}>
            I Have Paid
          </button>
        </div>
      )}

      {/* COD BUTTON */}
      {payment !== "qr" && (
        <div style={bottomBar}>
          <button onClick={handleSubmit} style={checkoutBtn}>
            Place Order
          </button>
        </div>
      )}
    </div>
  );
};

const container = {
  padding: "20px",
  maxWidth: "600px",
  margin: "auto",
};

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "15px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
  marginBottom: "20px",
};

const input = {
  width: "100%",
  padding: "10px",
  margin: "10px 0",
  borderRadius: "8px",
  border: "1px solid #ccc",
};

const radio = {
  display: "block",
  margin: "10px 0",
};

const bottomBar = {
  position: "sticky",
  bottom: "0",
  background: "#fff",
  padding: "15px",
  boxShadow: "0 -5px 15px rgba(0,0,0,0.1)",
};

const checkoutBtn = {
  width: "100%",
  padding: "12px",
  border: "none",
  borderRadius: "25px",
  background: "#ff4f87",
  color: "white",
  fontWeight: "600",
  cursor: "pointer",
};

export default Checkout;
